</section></main></div><div class="modal-wrap" id="modal"><div class="modal"><button class="close" id="close">×</button><p class="eyebrow">NUOVO WORKSPACE</p><h2 id="modalTitle">Aggiungi progetto</h2><form id="projectForm"><input type="hidden" id="projectId"><label>Nome progetto <input id="name" required placeholder="es. Portfolio personale"></label><label>Descrizione <textarea id="description" placeholder="Di cosa ti stai occupando?"></textarea></label><div class="row"><label>Stato<select id="status"><option value="active">In corso</option><option value="paused">In pausa</option><option value="completed">Completato</option></select></label><label>Provider<select id="provider"><option>GitHub</option><option>Gitea</option><option>GitLab</option></select></label></div><label>URL repository <input id="repo_url" type="url" placeholder="https://github.com/..." /></label><div class="row"><label>Ultimo commit <input id="last_commit" placeholder="es. fix: responsive header"></label><label>Data commit <input id="commit_date" type="date"></label></div><div class="form-actions"><button type="button" class="secondary" id="cancel">Annulla</button><button class="primary">Salva progetto</button></div></form></div></div><div class="modal-wrap" id="detailModal"><div class="modal detail-modal"><button class="close" id="detailClose">×</button><div id="detail"></div></div></div><div class="confirm-wrap" id="confirmWrap"><div class="confirm-box"><div class="confirm-icon">!</div><h3 id="confirmTitle">Confermi?</h3><p id="confirmMessage"></p><div class="confirm-actions"><button class="secondary" id="confirmCancel">Annulla</button><button class="danger" id="confirmOk">Elimina</button></div></div></div><div class="user-menu" id="userMenu"><button id="themeToggle">☼ Tema chiaro</button><button id="logoutBtn">↪ Esci</button></div><script src="assets/app.js"></script></body></html>
